@@ -117,14 +117,48 @@ public final class HttpApi {
                 || body.roomNumber() == null
                 || isBlank(body.guestName())
                 || isBlank(body.guestEmail())
-                || isBlank(body.guestCpf())
                 || body.checkIn() == null
                 || body.checkOut() == null
                 || body.guests() == null
                 || body.ratePlan() == null) {
             throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
         }
-        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
+
+        // Validate guest identification: exactly one type must be provided
+        boolean hasCpf = !isBlank(body.guestCpf());
+        boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
+        boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
+
+        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
+        if (identificationCount != 1) {
+            throw new HotelException(
+                    ErrorCode.INVALID_REQUEST,
+                    "provide exactly one guest identification: guestCpf, or companyCnpj with companyName, or guestPassport with guestCountry");
+        }
+
+        Guest guest;
+        if (hasCpf) {
+            guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf(), null, null, null, null);
+        } else if (hasCompany) {
+            guest = new Guest(
+                    body.guestName(),
+                    body.guestEmail(),
+                    null,
+                    body.companyCnpj(),
+                    body.companyName(),
+                    null,
+                    null);
+        } else {
+            guest = new Guest(
+                    body.guestName(),
+                    body.guestEmail(),
+                    null,
+                    null,
+                    null,
+                    body.guestPassport(),
+                    body.guestCountry());
+        }
+
         return new NewReservation(
                 body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
     }
